/**
 * Unit tests for org.apache.commons.lang.StringUtils#containsIgnoreCase
 */
public class StringUtils_containsIgnoreCase_TriageGen1Test {















    @Test
    public void testContainsIgnoreCase_EmptySearchStr() {
        // Based on the implementation: contains(str.toUpperCase(), "".toUpperCase())
        // StringUtils.contains("", "") is true, and StringUtils.contains("ABC", "") is true
        assertTrue("Should return true when searchStr is empty", 
            StringUtils.containsIgnoreCase("abc", ""));
        assertTrue("Should return true when both are empty", 
            StringUtils.containsIgnoreCase("", ""));
    }


}

